#!/usr/bin/env python3
# apply_tvx_hilo.py — TVX_HILO_20261007   (requires TVX_V1_20261007)
# ============================================================================
# TV Alerts: high / low between entry and exit, for the traded option AND the
# futures it is written on (MCX crude has no spot; the futures is the spot).
#   * live: option + futures in ONE quote every 2 s (no extra Kite calls)
#   * 2 min after exit: Kite 1-minute candles for the minutes strictly inside
#     the trade (wicks between quotes, gaps while the app slept)
#   * trades closed before this patch: candle-only range, marked "1M"
#   * page: "Range since entry" on the open position, a Futures ± column and a
#     click-to-expand range per closed trade; CSV gets every field + IST times
#   * DB: columns added in place on first start (ALTER TABLE ADD COLUMN);
#     nothing is dropped or rewritten
#
# Self-contained. RUN ONLY THIS SCRIPT.
#   cd ~/dev/scalp-app && python3 apply_tvx_hilo.py [--dry-run] [--allow-dirty]
#
# REPLACES (each must still be the exact TVX_V1 file — sha256-guarded):
#   backend/app/engine/tvx/{tvx_core,tvx_repo,tvx_engine,test_tvx}.py
#   backend/app/api/tvx_routes.py · frontend/src/pages/TvAlerts.jsx · docs/TVX_V1.md
# Mirrors into desktop/src-tauri/{backend,frontend} when those build copies exist.
# api_server.py and App.jsx are NOT touched.
# ============================================================================

import argparse, base64, hashlib, os, py_compile, shutil, subprocess, sys, tempfile
from pathlib import Path

FENCE = "TVX_HILO_20261007"
PARENT = "TVX_V1_20261007"
PAYLOADS = {
    'backend/app/engine/tvx/tvx_core.py': ('',
        '952f77efc022dce64d463791df224e9786d1afaeddb04875d70896231f50d0b8'),
    'backend/app/engine/tvx/tvx_repo.py': ('',
        '6eb22b5227dca88bc05d031b8178c6258903638639046723353106d5e135f77f'),
    'backend/app/engine/tvx/tvx_engine.py': ('',
        '145c30aca0769ecfaab718a344c73851d18992f99b1c847723c2d982d74bc86c'),
    'backend/app/engine/tvx/test_tvx.py': ('',
        'eb0ed80f5bedfd2f718504d906482bb1fd100dd75e2e6dff9a5de6ed5b2c1b17'),
    'backend/app/api/tvx_routes.py': ('',
        '4ade10501513b415c6197b2f600ff7e0779c5c4c7c0710bbcaab02df9fa4d5bd'),
    'frontend/src/pages/TvAlerts.jsx': ('',
        '0db061f0ad5c63deb48725d93dafabc4765bb0a601597628dbcc41074a80d00b'),
    'docs/TVX_V1.md': ('',
        '6a7b66fde7de1015173981a11d8fdfd6b28aa21cb5cf39187e218249733148f2'),
}
V1_SHA = {
    'backend/app/engine/tvx/tvx_core.py': '78aa04dd1970cd28ddbb7cd6c689ec251c11bfb87ce72448148f6eaf3fc3c1bb',
    'backend/app/engine/tvx/tvx_repo.py': 'da6fd1c82e914c996a02afdb3bcac98b02dd71f53f551fbd1b132fd93fc32ffd',
    'backend/app/engine/tvx/tvx_engine.py': '35a10faf1c5c0ffea895a971b549ffe6f060a8fdeaa3aa26347ffff618690652',
    'backend/app/engine/tvx/test_tvx.py': '290c0a5dc5f594ddd4956b8f1a998a03719aa0526b231653fad1bee0e4fa9f5b',
    'backend/app/api/tvx_routes.py': 'b924a647586ec01f7e75d142a2b6777a902f5bf3f26117336787a2037a0932e9',
    'frontend/src/pages/TvAlerts.jsx': 'd2394b3a7473cc18de816348b60bc60613c3609bd6b1d78d2530d238a6ff68c9',
    'docs/TVX_V1.md': 'df8afc1a1145c66a3ad5ac7a79ceafa76497b15f076a42e096af83fa8a605546',
}
MIRRORS = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}


def die(msg):
    print(f"\n✖ ABORT: {msg}\nNothing was written.")
    sys.exit(1)


def ok(msg):
    print(f"  ✓ {msg}")


def sha(b):
    return hashlib.sha256(b).hexdigest()


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--allow-dirty", action="store_true")
    args = ap.parse_args()
    root = Path.cwd()
    print(f"apply_tvx_hilo.py — {FENCE}  (repo: {root})\n")

    # 1. parent + fence
    api = root / "backend/app/api_server.py"
    if not api.is_file():
        die("backend/app/api_server.py not found — run from the scalp-app repo root")
    if PARENT not in api.read_text():
        die(f"{PARENT} is not applied — run apply_tvx_v1.py first")
    eng = root / "backend/app/engine/tvx/tvx_engine.py"
    if eng.is_file() and FENCE in eng.read_text():
        die(f"{FENCE} already present — already applied")
    ok(f"parent {PARENT} present, {FENCE} absent")

    # 2. every file to replace is byte-identical to the V1 delivery
    for p, want in V1_SHA.items():
        f = root / p
        if not f.is_file():
            die(f"{p} missing — TVX_V1 install incomplete")
        if sha(f.read_bytes()) != want:
            die(f"{p} differs from the TVX_V1 version (edited by hand or another patch). "
                f"Restore it (git checkout / the V1 apply) and re-run")
    ok(f"{len(V1_SHA)} TVX_V1 files verified unchanged (sha256)")

    # 3. git: an M on a target is a stop sign
    try:
        st = subprocess.run(["git", "status", "--porcelain", "--"] + list(V1_SHA), cwd=root,
                            capture_output=True, text=True, timeout=30).stdout
    except Exception:
        st = ""
    mods = [l for l in st.splitlines() if l[:2].strip().startswith("M")]
    if mods and not args.allow_dirty:
        die("targets have uncommitted modifications:\n" + "\n".join(mods) + "\nCommit first, or --allow-dirty")
    ok("git: no uncommitted edits on targets" if not mods else "dirty targets allowed")

    # 4. payloads
    new = {}
    for p, (b64, h) in PAYLOADS.items():
        data = base64.b64decode(b64)
        if sha(data) != h:
            die(f"payload checksum mismatch for {p}")
        new[p] = data.decode("utf-8")
    ok(f"{len(new)} payloads verified (sha256)")

    # 5. py_compile
    with tempfile.TemporaryDirectory() as td:
        for p, s in new.items():
            if p.endswith(".py"):
                f = Path(td) / p
                f.parent.mkdir(parents=True, exist_ok=True)
                f.write_text(s)
                try:
                    py_compile.compile(str(f), doraise=True)
                except py_compile.PyCompileError as e:
                    die(f"py_compile failed for {p}:\n{e}")
    ok("py_compile: all replaced Python files")

    # 6. full TVX suite (V1 + range) in a scratch copy of backend/
    with tempfile.TemporaryDirectory() as td:
        scratch = Path(td) / "backend"
        shutil.copytree(root / "backend" / "app", scratch / "app",
                        ignore=shutil.ignore_patterns("__pycache__", "*.bak-*", "*.pyc"))
        for p, s in new.items():
            if p.startswith("backend/"):
                (scratch / p[len("backend/"):]).write_text(s)
        r = subprocess.run([sys.executable, "-m", "app.engine.tvx.test_tvx"], cwd=scratch,
                           capture_output=True, text=True, timeout=300)
        if r.returncode != 0:
            print(r.stdout[-6000:], r.stderr[-3000:])
            die("TVX suite failed (output above)")
        ok(f"TVX suite: {r.stdout.count('  PASS  ')} checks passed ({r.stdout.strip().splitlines()[-1]})")

    # 7. esbuild parse
    esb = next((c for c in (root / "frontend/node_modules/.bin/esbuild",
                            root / "desktop/node_modules/.bin/esbuild",
                            root / "desktop/src-tauri/frontend/node_modules/.bin/esbuild") if c.exists()), None) \
        or shutil.which("esbuild")
    if esb:
        with tempfile.TemporaryDirectory() as td:
            f = Path(td) / "TvAlerts.jsx"
            f.write_text(new["frontend/src/pages/TvAlerts.jsx"])
            r = subprocess.run([str(esb), str(f), "--loader:.jsx=jsx", "--jsx=automatic", "--log-level=error"],
                               capture_output=True, text=True, timeout=60)
            if r.returncode != 0:
                die(f"esbuild could not parse TvAlerts.jsx:\n{r.stderr[-2000:]}")
        ok(f"esbuild parsed TvAlerts.jsx ({esb})")
    else:
        print("  ! esbuild not found — JSX parse skipped (build-scalp.sh will compile it)")

    # 8. plan
    plan = []
    for p, s in new.items():
        plan.append(root / p)
        for src, dst in MIRRORS.items():
            if p.startswith(src) and (root / dst).is_dir():
                plan.append(root / (dst + p[len(src):]))
    content = {}
    for f in plan:
        rel = str(f.relative_to(root))
        for src, dst in MIRRORS.items():
            if rel.startswith(dst):
                rel = src + rel[len(dst):]
        content[f] = new[rel]
    if args.dry_run:
        print("\nDRY RUN — would replace:")
        for f in plan:
            print(f"    {f.relative_to(root)}")
        print("\nAll gates passed. Re-run without --dry-run to apply.")
        return

    # 9. staged all-or-nothing
    done = []
    try:
        for f in plan:
            if f.exists():
                bak = f.with_name(f.name + f".bak-{FENCE}")
                shutil.copy2(f, bak)
                done.append((f, bak))
            else:
                done.append((f, None))
            f.parent.mkdir(parents=True, exist_ok=True)
            tmp = f.with_name(f.name + ".hilo-tmp")
            tmp.write_text(content[f])
            os.replace(tmp, f)
    except Exception as e:
        for f, bak in reversed(done):
            if bak:
                shutil.copy2(bak, f)
                bak.unlink(missing_ok=True)
            else:
                f.unlink(missing_ok=True)
        die(f"write failed ({e}) — rolled back")

    print("\nReplaced:")
    for f, _ in done:
        print(f"    {f.relative_to(root)}")
    print(f"""
✔ {FENCE} applied.

Next:
  1. git add backend/app/engine/tvx backend/app/api/tvx_routes.py frontend/src/pages/TvAlerts.jsx docs/TVX_V1.md
     git commit -m "{FENCE}: TV Alerts trade range (option + futures high/low)"
  2. ./desktop/build-scalp.sh both
  On first start the tvx_trades table gains its new columns in place; trades
  already closed get a 1-minute-candle range within a few minutes.
""")


if __name__ == "__main__":
    main()
